// The check for a file generated by scripts/gen/source-backfill-sql.mjs (kept apart from the generator, which needs the classify rules and the "@/" register hook; migration-checks runs on plain node).
// The file cannot be re-rendered without the live export, so it is held to what it states about itself: the `-- source-export:` header names the export file and its sha256, and the UPDATE statements in the
// file are exactly the ones its GENERATED line counts (one per source_role planned, one per source_type planned).
export function checkBackfill(sql) {
  const text = sql.replace(/\r\n/g, "\n");
  const problems = [];
  const header = /^-- source-export: (\S+) \(sha256 ([0-9a-f]{64})\)$/m.exec(text);
  if (!header) problems.push("no `-- source-export:` header naming the export file and its sha256 (regenerate: node --import ./tests/_support/register.mjs scripts/gen/source-backfill-sql.mjs <export.json> <label>)");
  const line = /^-- GENERATED by scripts\/gen\/source-backfill-sql\.mjs from .* \((\d+) registry rows read, (\d+) planned: (\d+) source_role, (\d+) source_type\)\.$/m.exec(text);
  if (!line) return [...problems, "the GENERATED line does not state the rows read, the planned count and the source_role / source_type counts"];
  const [, , planned, roles, types] = line.map(Number);
  if (planned > roles + types || planned < Math.max(roles, types)) problems.push(`the GENERATED line is inconsistent: ${planned} planned rows cannot carry ${roles} source_role and ${types} source_type`);
  const count = (col) => [...text.matchAll(new RegExp(`^UPDATE public\.sources SET ${col} = `, "gm"))].length;
  if (count("source_role") !== roles) problems.push(`the file has ${count("source_role")} source_role UPDATE statements, its GENERATED line says ${roles}`);
  if (count("source_type") !== types) problems.push(`the file has ${count("source_type")} source_type UPDATE statements, its GENERATED line says ${types}`);
  return problems;
}
